   556  static int
   557  cmp_func_motorola (const void *elem1, const void *elem2)
   558  {
   559          return cmp_func ((const unsigned char *) elem1,
   560                           (const unsigned char *) elem2, EXIF_BYTE_ORDER_MOTOROLA);
   561  }
